-- ---------------------------------------------------------------------------
-- 0001_schema.sql
-- ---------------------------------------------------------------------------
-- VE-gear :: 0001 schema
-- Core tables for storefront + merchant panel.
-- Postgres / Supabase. Run in order 0001..0005.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
do $$ begin
  create type user_role as enum ('admin', 'editor', 'viewer');
exception when duplicate_object then null; end $$;

do $$ begin
  create type order_status as enum (
    'pending', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled'
  );
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- Profiles (mirrors auth.users, holds role)
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  full_name   text,
  role        user_role not null default 'viewer',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Catalog
-- ---------------------------------------------------------------------------
create table if not exists public.categories (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  slug        text not null unique,
  description text,
  image_path  text,
  sort        int not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists public.products (
  id             uuid primary key default gen_random_uuid(),
  title          text not null,
  slug           text not null unique,
  original_price numeric(12,2) not null default 0,
  current_price  numeric(12,2) not null default 0,
  description    jsonb,                       -- { "html": "<p>..</p>" }
  status         text not null default 'active', -- active | draft | archived
  product_type   text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists products_status_idx on public.products (status);

create table if not exists public.product_images (
  id         uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  path       text not null,
  alt        text,
  is_main    boolean not null default false,
  sort       int not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists product_images_product_idx on public.product_images (product_id);

create table if not exists public.product_variants (
  id                  uuid primary key default gen_random_uuid(),
  product_id          uuid not null references public.products (id) on delete cascade,
  size                text,
  color               text,
  sku                 text,
  price_override      numeric(12,2),
  stock_quantity      int not null default 0,
  low_stock_threshold int not null default 5,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (product_id, size, color)
);
create index if not exists product_variants_product_idx on public.product_variants (product_id);

create table if not exists public.product_categories (
  product_id  uuid not null references public.products (id) on delete cascade,
  category_id uuid not null references public.categories (id) on delete cascade,
  primary key (product_id, category_id)
);

-- ---------------------------------------------------------------------------
-- Customers + orders
-- ---------------------------------------------------------------------------
create table if not exists public.customers (
  id           uuid primary key default gen_random_uuid(),
  name         text,
  phone        text unique,
  email        text,
  address      jsonb,
  orders_count int not null default 0,
  total_spent  numeric(12,2) not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create sequence if not exists order_number_seq start 1001;

create table if not exists public.orders (
  id             uuid primary key default gen_random_uuid(),
  order_number   text not null unique default ('VE-' || nextval('order_number_seq')::text),
  status         order_status not null default 'pending',
  customer_id    uuid references public.customers (id) on delete set null,
  delivery       jsonb not null,   -- { country, firstName, lastName, address, city, postalCode, phone }
  totals         jsonb not null,   -- { subtotal, shipping, total }
  payment_method text not null default 'cod',
  notes          text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists orders_status_idx on public.orders (status);
create index if not exists orders_customer_idx on public.orders (customer_id);
create index if not exists orders_created_idx on public.orders (created_at desc);

create table if not exists public.order_items (
  id         uuid primary key default gen_random_uuid(),
  order_id   uuid not null references public.orders (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  variant_id uuid references public.product_variants (id) on delete set null,
  title      text,          -- snapshot of product title at purchase time
  size       text,
  color      text,
  quantity   int not null default 1,
  unit_price numeric(12,2) not null default 0
);
create index if not exists order_items_order_idx on public.order_items (order_id);

-- ---------------------------------------------------------------------------
-- Content
-- ---------------------------------------------------------------------------
create table if not exists public.promotions (
  id               uuid primary key default gen_random_uuid(),
  title            text not null,
  description      text,
  image_path       text,
  discount_percent numeric(5,2),
  active           boolean not null default true,
  starts_at        timestamptz,
  ends_at          timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create table if not exists public.reviews (
  id            uuid primary key default gen_random_uuid(),
  customer_name text,
  image_path    text,
  rating        int check (rating between 1 and 5),
  body          text,
  product_id    uuid references public.products (id) on delete set null,
  is_published  boolean not null default true,
  created_at    timestamptz not null default now()
);

create table if not exists public.contact_submissions (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  email        text not null,
  phone        text,
  message      text not null,
  is_read      boolean not null default false,
  submitted_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Settings + operations
-- ---------------------------------------------------------------------------
create table if not exists public.site_settings (
  id                     int primary key default 1 check (id = 1),
  store_name             text not null default 'VE-gear',
  logo_path              text,
  contact_email          text,
  contact_phone          text,
  address                text,
  currency               text not null default 'USD',
  currency_symbol        text not null default '$',
  shipping_flat          numeric(12,2) not null default 0,
  free_shipping_threshold numeric(12,2),
  socials                jsonb not null default '{}'::jsonb,
  google_analytics_id    text,
  meta_pixel_id          text,
  gtm_id                 text,
  analytics_enabled      boolean not null default false,
  security_enabled       boolean not null default false,
  updated_at             timestamptz not null default now()
);

create table if not exists public.blocked_ips (
  id         uuid primary key default gen_random_uuid(),
  ip         text not null unique,
  reason     text,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 0002_functions_triggers.sql
-- ---------------------------------------------------------------------------
-- VE-gear :: 0002 functions & triggers

-- ---------------------------------------------------------------------------
-- Role helpers (used by RLS). SECURITY DEFINER so policies can read profiles
-- without recursive RLS checks.
-- ---------------------------------------------------------------------------
create or replace function public.current_role()
returns user_role
language sql
stable
security definer
set search_path = public
as $$
  select role from public.profiles where id = auth.uid();
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select role from public.profiles where id = auth.uid()) = 'admin', false);
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select role from public.profiles where id = auth.uid()) in ('admin', 'editor'),
    false
  );
$$;

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'profiles','categories','products','product_variants','customers',
    'orders','promotions','site_settings'
  ] loop
    execute format(
      'drop trigger if exists trg_touch_%1$s on public.%1$s;
       create trigger trg_touch_%1$s before update on public.%1$s
         for each row execute function public.touch_updated_at();', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- New auth user -> profile. First ever user becomes admin, rest viewer.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  assigned user_role;
begin
  if not exists (select 1 from public.profiles) then
    assigned := 'admin';
  else
    assigned := 'viewer';
  end if;

  insert into public.profiles (id, full_name, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.email),
    assigned
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Customer upsert + aggregates driven from orders
-- ---------------------------------------------------------------------------
create or replace function public.resolve_order_customer()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_phone text := nullif(trim(new.delivery ->> 'phone'), '');
  v_name  text := trim(coalesce(new.delivery ->> 'firstName','') || ' ' || coalesce(new.delivery ->> 'lastName',''));
  v_customer_id uuid;
begin
  if new.customer_id is not null then
    return new;
  end if;

  if v_phone is null then
    return new; -- no phone, cannot dedupe; leave customer_id null
  end if;

  select id into v_customer_id from public.customers where phone = v_phone;

  if v_customer_id is null then
    insert into public.customers (name, phone, address)
    values (nullif(v_name,''), v_phone, new.delivery)
    returning id into v_customer_id;
  else
    update public.customers
      set name = coalesce(nullif(v_name,''), name),
          address = new.delivery,
          updated_at = now()
      where id = v_customer_id;
  end if;

  new.customer_id := v_customer_id;
  return new;
end;
$$;

drop trigger if exists trg_resolve_order_customer on public.orders;
create trigger trg_resolve_order_customer
  before insert on public.orders
  for each row execute function public.resolve_order_customer();

create or replace function public.recompute_customer_totals(p_customer_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  update public.customers c set
    orders_count = coalesce(agg.cnt, 0),
    total_spent  = coalesce(agg.spent, 0),
    updated_at   = now()
  from (
    select
      count(*) filter (where status <> 'cancelled') as cnt,
      sum((totals ->> 'total')::numeric) filter (where status <> 'cancelled') as spent
    from public.orders
    where customer_id = p_customer_id
  ) agg
  where c.id = p_customer_id;
$$;

create or replace function public.after_order_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'DELETE' then
    if old.customer_id is not null then
      perform public.recompute_customer_totals(old.customer_id);
    end if;
    return old;
  end if;

  if new.customer_id is not null then
    perform public.recompute_customer_totals(new.customer_id);
  end if;
  if tg_op = 'UPDATE' and old.customer_id is distinct from new.customer_id
     and old.customer_id is not null then
    perform public.recompute_customer_totals(old.customer_id);
  end if;
  return new;
end;
$$;

drop trigger if exists trg_after_order_change on public.orders;
create trigger trg_after_order_change
  after insert or update or delete on public.orders
  for each row execute function public.after_order_change();

-- ---------------------------------------------------------------------------
-- place_order RPC: atomic order + items, customer handled by trigger above.
-- Callable by anon (storefront checkout). SECURITY DEFINER bypasses RLS.
-- payload:
--   { delivery:{...}, items:[{product_id,variant_id,size,color,quantity,unit_price,title}],
--     totals:{subtotal,shipping,total}, notes }
-- ---------------------------------------------------------------------------
create or replace function public.place_order(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order_id uuid;
  v_order_number text;
  item jsonb;
begin
  if payload -> 'delivery' is null or payload -> 'items' is null or payload -> 'totals' is null then
    raise exception 'delivery, items and totals are required';
  end if;

  insert into public.orders (delivery, totals, notes)
  values (payload -> 'delivery', payload -> 'totals', nullif(payload ->> 'notes',''))
  returning id, order_number into v_order_id, v_order_number;

  for item in select * from jsonb_array_elements(payload -> 'items') loop
    insert into public.order_items
      (order_id, product_id, variant_id, title, size, color, quantity, unit_price)
    values (
      v_order_id,
      nullif(item ->> 'product_id','')::uuid,
      nullif(item ->> 'variant_id','')::uuid,
      item ->> 'title',
      item ->> 'size',
      item ->> 'color',
      coalesce((item ->> 'quantity')::int, 1),
      coalesce((item ->> 'unit_price')::numeric, 0)
    );

    -- decrement stock if a variant was specified
    if nullif(item ->> 'variant_id','') is not null then
      update public.product_variants
        set stock_quantity = greatest(0, stock_quantity - coalesce((item ->> 'quantity')::int, 1))
        where id = (item ->> 'variant_id')::uuid;
    end if;
  end loop;

  return jsonb_build_object('id', v_order_id, 'order_number', v_order_number);
end;
$$;

grant execute on function public.place_order(jsonb) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 0003_rls.sql
-- ---------------------------------------------------------------------------
-- VE-gear :: 0003 row level security
-- Model:
--   public (anon) : read published storefront data; insert contact submissions.
--   staff (admin/editor) : full CRUD on catalog/orders/content.
--   admin : users/roles + settings + blocked_ips.
--   orders/order_items are written only through place_order() (SECURITY DEFINER),
--     so no anon insert policy is needed there.

alter table public.profiles            enable row level security;
alter table public.categories          enable row level security;
alter table public.products            enable row level security;
alter table public.product_images      enable row level security;
alter table public.product_variants    enable row level security;
alter table public.product_categories  enable row level security;
alter table public.customers           enable row level security;
alter table public.orders              enable row level security;
alter table public.order_items         enable row level security;
alter table public.promotions          enable row level security;
alter table public.reviews             enable row level security;
alter table public.contact_submissions enable row level security;
alter table public.site_settings       enable row level security;
alter table public.blocked_ips         enable row level security;

-- helper to (re)create a policy idempotently
-- (Postgres has no "create policy if not exists"; drop first.)

-- ---- profiles ----
drop policy if exists profiles_self_read on public.profiles;
create policy profiles_self_read on public.profiles
  for select using (id = auth.uid() or public.is_admin());

drop policy if exists profiles_admin_write on public.profiles;
create policy profiles_admin_write on public.profiles
  for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists profiles_self_update on public.profiles;
create policy profiles_self_update on public.profiles
  for update using (id = auth.uid())
  with check (id = auth.uid() and role = (select role from public.profiles where id = auth.uid()));

-- ---- categories ----
drop policy if exists categories_public_read on public.categories;
create policy categories_public_read on public.categories for select using (true);
drop policy if exists categories_staff_write on public.categories;
create policy categories_staff_write on public.categories
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- products ----
drop policy if exists products_public_read on public.products;
create policy products_public_read on public.products
  for select using (status = 'active' or public.is_staff());
drop policy if exists products_staff_write on public.products;
create policy products_staff_write on public.products
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- product_images ----
drop policy if exists product_images_public_read on public.product_images;
create policy product_images_public_read on public.product_images for select using (true);
drop policy if exists product_images_staff_write on public.product_images;
create policy product_images_staff_write on public.product_images
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- product_variants ----
drop policy if exists product_variants_public_read on public.product_variants;
create policy product_variants_public_read on public.product_variants for select using (true);
drop policy if exists product_variants_staff_write on public.product_variants;
create policy product_variants_staff_write on public.product_variants
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- product_categories ----
drop policy if exists product_categories_public_read on public.product_categories;
create policy product_categories_public_read on public.product_categories for select using (true);
drop policy if exists product_categories_staff_write on public.product_categories;
create policy product_categories_staff_write on public.product_categories
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- customers (staff only; storefront never reads these) ----
drop policy if exists customers_staff_read on public.customers;
create policy customers_staff_read on public.customers for select using (public.is_staff());
drop policy if exists customers_staff_write on public.customers;
create policy customers_staff_write on public.customers
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- orders (staff manage; storefront writes via place_order RPC) ----
drop policy if exists orders_staff_read on public.orders;
create policy orders_staff_read on public.orders for select using (public.is_staff());
drop policy if exists orders_staff_write on public.orders;
create policy orders_staff_write on public.orders
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- order_items ----
drop policy if exists order_items_staff_read on public.order_items;
create policy order_items_staff_read on public.order_items for select using (public.is_staff());
drop policy if exists order_items_staff_write on public.order_items;
create policy order_items_staff_write on public.order_items
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- promotions ----
drop policy if exists promotions_public_read on public.promotions;
create policy promotions_public_read on public.promotions
  for select using (active or public.is_staff());
drop policy if exists promotions_staff_write on public.promotions;
create policy promotions_staff_write on public.promotions
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- reviews ----
drop policy if exists reviews_public_read on public.reviews;
create policy reviews_public_read on public.reviews
  for select using (is_published or public.is_staff());
drop policy if exists reviews_staff_write on public.reviews;
create policy reviews_staff_write on public.reviews
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- contact_submissions (anyone may submit; staff read/manage) ----
drop policy if exists contact_public_insert on public.contact_submissions;
create policy contact_public_insert on public.contact_submissions
  for insert with check (true);
drop policy if exists contact_staff_read on public.contact_submissions;
create policy contact_staff_read on public.contact_submissions
  for select using (public.is_staff());
drop policy if exists contact_staff_write on public.contact_submissions;
create policy contact_staff_write on public.contact_submissions
  for all using (public.is_staff()) with check (public.is_staff());

-- ---- site_settings (public read for storefront branding/analytics; admin write) ----
drop policy if exists site_settings_public_read on public.site_settings;
create policy site_settings_public_read on public.site_settings for select using (true);
drop policy if exists site_settings_admin_write on public.site_settings;
create policy site_settings_admin_write on public.site_settings
  for all using (public.is_admin()) with check (public.is_admin());

-- ---- blocked_ips (admin only) ----
drop policy if exists blocked_ips_admin_all on public.blocked_ips;
create policy blocked_ips_admin_all on public.blocked_ips
  for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists blocked_ips_staff_read on public.blocked_ips;
create policy blocked_ips_staff_read on public.blocked_ips
  for select using (public.is_staff());

-- ---------------------------------------------------------------------------
-- 0004_storage.sql
-- ---------------------------------------------------------------------------
-- VE-gear :: 0004 storage buckets & policies
-- Public read; writes restricted to staff (admin/editor).

insert into storage.buckets (id, name, public)
values
  ('product-images',   'product-images',   true),
  ('category-images',  'category-images',  true),
  ('review-images',    'review-images',    true),
  ('promotion-images', 'promotion-images', true),
  ('branding',         'branding',         true)
on conflict (id) do nothing;

-- Public read for every VE-gear bucket
drop policy if exists "vegear public read" on storage.objects;
create policy "vegear public read" on storage.objects
  for select using (
    bucket_id in ('product-images','category-images','review-images','promotion-images','branding')
  );

-- Staff insert
drop policy if exists "vegear staff insert" on storage.objects;
create policy "vegear staff insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id in ('product-images','category-images','review-images','promotion-images','branding')
    and public.is_staff()
  );

-- Staff update
drop policy if exists "vegear staff update" on storage.objects;
create policy "vegear staff update" on storage.objects
  for update to authenticated
  using (
    bucket_id in ('product-images','category-images','review-images','promotion-images','branding')
    and public.is_staff()
  )
  with check (
    bucket_id in ('product-images','category-images','review-images','promotion-images','branding')
    and public.is_staff()
  );

-- Staff delete
drop policy if exists "vegear staff delete" on storage.objects;
create policy "vegear staff delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id in ('product-images','category-images','review-images','promotion-images','branding')
    and public.is_staff()
  );

