create or replace function public.save_courier_settings(
  p_settings jsonb,
  p_active_provider text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  item jsonb;
  item_provider text;
begin
  if not public.is_admin() then
    raise exception 'permission denied';
  end if;
  if p_active_provider is not null
     and p_active_provider not in ('pathao', 'steadfast', 'redx') then
    raise exception 'invalid courier provider';
  end if;

  update public.courier_settings set active = false where active;

  for item in select value from jsonb_array_elements(p_settings)
  loop
    item_provider := item ->> 'provider';
    if item_provider not in ('pathao', 'steadfast', 'redx') then
      raise exception 'invalid courier provider';
    end if;

    insert into public.courier_settings (
      provider, active, sandbox, client_id, client_secret, username, password,
      api_key, secret_key, access_token, pickup_store_id, webhook_secret,
      updated_at
    ) values (
      item_provider,
      item_provider = p_active_provider,
      coalesce((item ->> 'sandbox')::boolean, false),
      nullif(item ->> 'client_id', ''),
      nullif(item ->> 'client_secret', ''),
      nullif(item ->> 'username', ''),
      nullif(item ->> 'password', ''),
      nullif(item ->> 'api_key', ''),
      nullif(item ->> 'secret_key', ''),
      nullif(item ->> 'access_token', ''),
      nullif(item ->> 'pickup_store_id', ''),
      nullif(item ->> 'webhook_secret', ''),
      now()
    )
    on conflict (provider) do update set
      active = excluded.active,
      sandbox = excluded.sandbox,
      client_id = excluded.client_id,
      client_secret = excluded.client_secret,
      username = excluded.username,
      password = excluded.password,
      api_key = excluded.api_key,
      secret_key = excluded.secret_key,
      access_token = excluded.access_token,
      pickup_store_id = excluded.pickup_store_id,
      webhook_secret = excluded.webhook_secret,
      updated_at = now();
  end loop;
end;
$$;

revoke all on function public.save_courier_settings(jsonb, text) from public;
grant execute on function public.save_courier_settings(jsonb, text) to authenticated;

-- Lock-check, restock, and delete in one transaction. The shipment foreign key
-- remains the final guard if a courier sync races with this function.
create or replace function public.delete_orders_safely(p_order_ids uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_orders jsonb;
begin
  if not public.is_staff() then
    raise exception 'permission denied';
  end if;

  perform 1
  from public.orders
  where id = any(p_order_ids)
  for update;

  if exists (
    select 1
    from public.order_shipments
    where order_id = any(p_order_ids)
  ) then
    raise exception 'courier-synced orders cannot be deleted';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', id,
        'order_number', order_number,
        'status', status
      )
      order by created_at
    ),
    '[]'::jsonb
  )
  into v_orders
  from public.orders
  where id = any(p_order_ids);

  with quantities as (
    select oi.variant_id, sum(oi.quantity)::int as quantity
    from public.order_items oi
    join public.orders o on o.id = oi.order_id
    where o.id = any(p_order_ids)
      and o.status in ('pending', 'confirmed', 'processing')
      and oi.variant_id is not null
    group by oi.variant_id
  )
  update public.product_variants variant
  set stock_quantity = greatest(0, variant.stock_quantity + quantities.quantity),
      updated_at = now()
  from quantities
  where variant.id = quantities.variant_id;

  delete from public.orders where id = any(p_order_ids);
  return v_orders;
end;
$$;

revoke all on function public.delete_orders_safely(uuid[]) from public;
grant execute on function public.delete_orders_safely(uuid[]) to authenticated;

create or replace function public.delete_customers_safely(p_customer_ids uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_customers jsonb;
  v_order_ids uuid[];
begin
  if not public.is_staff() then
    raise exception 'permission denied';
  end if;

  perform 1
  from public.customers
  where id = any(p_customer_ids)
  for update;

  select coalesce(
    jsonb_agg(jsonb_build_object('id', id, 'name', name, 'phone', phone)),
    '[]'::jsonb
  )
  into v_customers
  from public.customers
  where id = any(p_customer_ids);

  select coalesce(array_agg(id), array[]::uuid[])
  into v_order_ids
  from public.orders
  where customer_id = any(p_customer_ids);

  if cardinality(v_order_ids) > 0 then
    perform public.delete_orders_safely(v_order_ids);
  end if;

  delete from public.customers where id = any(p_customer_ids);
  return v_customers;
end;
$$;

revoke all on function public.delete_customers_safely(uuid[]) from public;
grant execute on function public.delete_customers_safely(uuid[]) to authenticated;

create or replace function public.cancel_order_safely(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status public.order_status;
begin
  if not public.is_staff() then
    raise exception 'permission denied';
  end if;

  select status into v_status
  from public.orders
  where id = p_order_id
  for update;

  if v_status is null then
    raise exception 'order not found';
  end if;
  if v_status in ('delivered', 'cancelled') then
    raise exception 'order cannot be cancelled';
  end if;
  if exists (
    select 1 from public.order_shipments where order_id = p_order_id
  ) then
    raise exception 'courier-synced orders cannot be cancelled';
  end if;

  with quantities as (
    select variant_id, sum(quantity)::int as quantity
    from public.order_items
    where order_id = p_order_id and variant_id is not null
    group by variant_id
  )
  update public.product_variants variant
  set stock_quantity = greatest(0, variant.stock_quantity + quantities.quantity),
      updated_at = now()
  from quantities
  where variant.id = quantities.variant_id;

  update public.orders
  set status = 'cancelled', updated_at = now()
  where id = p_order_id;
end;
$$;

revoke all on function public.cancel_order_safely(uuid) from public;
grant execute on function public.cancel_order_safely(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 0018_abandoned_gateway_orders.sql
-- ---------------------------------------------------------------------------
-- Remove incomplete gateway orders and return reserved stock.

create or replace function public.delete_unpaid_gateway_order(p_order_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order_id uuid;
begin
  select id into v_order_id
  from public.orders
  where id = p_order_id
    and payment_method <> 'cod'
    and payment_status <> 'paid'
  for update;

  if v_order_id is null then
    return false;
  end if;
  if exists (
    select 1 from public.order_shipments where order_id = p_order_id
  ) then
    return false;
  end if;

  with quantities as (
    select variant_id, sum(quantity)::int as quantity
    from public.order_items
    where order_id = p_order_id and variant_id is not null
    group by variant_id
  )
  update public.product_variants variant
  set stock_quantity = greatest(0, variant.stock_quantity + quantities.quantity),
      updated_at = now()
  from quantities
  where variant.id = quantities.variant_id;

  delete from public.orders where id = p_order_id;
  return true;
end;
$$;

revoke all on function public.delete_unpaid_gateway_order(uuid) from public;
grant execute on function public.delete_unpaid_gateway_order(uuid) to service_role;

create or replace function public.cleanup_abandoned_gateway_orders(
  p_cutoff timestamptz default (now() - interval '1 hour')
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  candidate record;
  deleted_numbers text[] := array[]::text[];
begin
  for candidate in
    select id, order_number
    from public.orders
    where payment_method <> 'cod'
      and payment_status = 'unpaid'
      and created_at < p_cutoff
    order by created_at
    for update skip locked
  loop
    if public.delete_unpaid_gateway_order(candidate.id) then
      deleted_numbers := array_append(deleted_numbers, candidate.order_number);
    end if;
  end loop;

  return jsonb_build_object(
    'count', cardinality(deleted_numbers),
    'order_numbers', to_jsonb(deleted_numbers)
  );
end;
$$;

revoke all on function public.cleanup_abandoned_gateway_orders(timestamptz) from public;
grant execute on function public.cleanup_abandoned_gateway_orders(timestamptz) to service_role;

create extension if not exists pg_cron with schema pg_catalog;

do $$
declare
  existing_job record;
begin
  for existing_job in
    select jobid from cron.job where jobname = 'cleanup-abandoned-gateway-orders'
  loop
    perform cron.unschedule(existing_job.jobid);
  end loop;

  perform cron.schedule(
    'cleanup-abandoned-gateway-orders',
    '*/15 * * * *',
    $job$select public.cleanup_abandoned_gateway_orders(now() - interval '1 hour');$job$
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 0047_sms_otp_settings.sql
-- ---------------------------------------------------------------------------
-- Khudebarta SMS gateway configuration and checkout OTP verification.

create table if not exists public.sms_settings (
  id           int primary key default 1 check (id = 1),
  enabled      boolean not null default false,
  sender_id    text,
  api_key      text,
  secret_key   text,
  checkout_otp boolean not null default false,
  updated_at   timestamptz not null default now()
);

insert into public.sms_settings (id)
values (1)
on conflict (id) do nothing;

alter table public.sms_settings enable row level security;

drop policy if exists sms_settings_admin_all on public.sms_settings;
create policy sms_settings_admin_all on public.sms_settings
  for all using (public.is_admin()) with check (public.is_admin());

drop trigger if exists trg_touch_sms_settings on public.sms_settings;
create trigger trg_touch_sms_settings
  before update on public.sms_settings
  for each row execute function public.touch_updated_at();

create table if not exists public.sms_otps (
  id          uuid primary key default gen_random_uuid(),
  phone       text not null,
  code_hash   text not null,
  salt        text not null,
  expires_at  timestamptz not null,
  attempts    int not null default 0,
  used        boolean not null default false,
  created_at  timestamptz not null default now()
);

create index if not exists sms_otps_phone_created_idx
  on public.sms_otps (phone, created_at desc);

alter table public.sms_otps enable row level security;

-- Neutral defaults for new client stores. Client initialization can replace them.
alter table public.orders
  alter column order_number set default ('ORD-' || nextval('order_number_seq')::text);
alter table public.site_settings
  alter column store_name set default 'Store';
alter table public.email_smtp_settings
  alter column from_name set default 'Store';

update public.site_settings
set store_name = 'Store', contact_email = null
where id = 1;

update public.email_smtp_settings
set from_name = 'Store'
where id = 1;

commit;
